//! A catalog of the tags PCGen understands, generated by
//! `tools/gen_catalog.py` into `tags.tsv`.  Each entry names a scope
//! (a file kind such as `SPELL`, a line type such as `CLASSLEVEL`, a
//! token family such as `PRE` or `BONUS`, or `GLOBAL` for tags valid
//! on every object), a tag, and whether the tag is deprecated.

use crate::lst::kind::FileKind;
use serde::Serialize;
use std::collections::{BTreeMap, HashMap};
use std::sync::OnceLock;

const TAGS_TSV: &str = include_str!("tags.tsv");

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize)]
#[serde(rename_all = "lowercase")]
pub enum Status {
    Active,
    Deprecated,
}

#[derive(Debug, Clone, Serialize)]
pub struct Entry {
    pub scope: String,
    pub tag: String,
    pub status: Status,
    /// where the fact was found: "code", "docs", or both
    pub evidence: String,
}

#[derive(Debug, Default)]
pub struct Catalog {
    pub entries: Vec<Entry>,
    by_scope: HashMap<String, HashMap<String, usize>>,
}

impl Catalog {
    pub fn parse(tsv: &str) -> Catalog {
        let mut c = Catalog::default();
        for line in tsv.lines() {
            if line.starts_with('#') || line.trim().is_empty() {
                continue;
            }
            let f: Vec<&str> = line.split('\t').collect();
            if f.len() < 3 {
                continue;
            }
            let e = Entry {
                scope: f[0].to_string(),
                tag: f[1].to_string(),
                status: if f[2] == "deprecated" {
                    Status::Deprecated
                } else {
                    Status::Active
                },
                evidence: f.get(3).unwrap_or(&"").to_string(),
            };
            c.by_scope
                .entry(e.scope.clone())
                .or_default()
                .insert(e.tag.clone(), c.entries.len());
            c.entries.push(e);
        }
        c
    }

    /// The built-in catalog.
    pub fn get() -> &'static Catalog {
        static CAT: OnceLock<Catalog> = OnceLock::new();
        CAT.get_or_init(|| Catalog::parse(TAGS_TSV))
    }

    pub fn lookup(&self, scope: &str, tag: &str) -> Option<&Entry> {
        self.by_scope
            .get(scope)?
            .get(tag)
            .map(|&i| &self.entries[i])
    }

    /// Scopes consulted for a tag on an object line of `kind`, with
    /// `line_tag` naming a sub-line type where relevant (`LEVEL`,
    /// `SUBCLASS`, kit line tags).
    pub fn scopes_for(kind: FileKind, line_tag: Option<&str>) -> Vec<String> {
        let mut v = vec![kind.tag().to_string(), "GLOBAL".to_string()];
        match kind {
            FileKind::Ability | FileKind::Feat => {
                v.push("ABILITY".into());
                v.push("FEAT".into());
            }
            FileKind::Class => {
                v.push("CLASSLEVEL".into());
                if matches!(
                    line_tag,
                    Some("SUBCLASS" | "SUBSTITUTIONCLASS" | "SUBCLASSLEVEL" | "SUBSTITUTIONLEVEL")
                ) {
                    v.push("SUBCLASS".into());
                }
            }
            _ => {}
        }
        v
    }

    /// Check a tag used on an object line.  Returns None if the tag is
    /// unknown in every applicable scope.
    pub fn check(&self, kind: FileKind, line_tag: Option<&str>, tag: &str) -> Option<&Entry> {
        let t = tag.strip_prefix('!').unwrap_or(tag);
        if t.starts_with("PRE") && t != "PRE" {
            return self.lookup("PRE", t);
        }
        Catalog::scopes_for(kind, line_tag)
            .iter()
            .find_map(|s| self.lookup(s, t))
    }

    /// Is the tag known in any scope?
    pub fn known_anywhere(&self, tag: &str) -> bool {
        self.by_scope.values().any(|m| m.contains_key(tag))
    }

    /// All entries grouped by scope.
    pub fn by_scope(&self) -> BTreeMap<&str, Vec<&Entry>> {
        let mut m: BTreeMap<&str, Vec<&Entry>> = BTreeMap::new();
        for e in &self.entries {
            m.entry(e.scope.as_str()).or_default().push(e);
        }
        m
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn builtin_catalog() {
        let c = Catalog::get();
        assert!(c.entries.len() > 500);
        assert!(c.check(FileKind::Spell, None, "SCHOOL").is_some());
        assert!(c.check(FileKind::Spell, None, "BONUS").is_some());
        assert!(c.check(FileKind::Spell, None, "!PREABILITY").is_some());
        assert!(c.check(FileKind::Class, Some("LEVEL"), "CAST").is_some());
        assert!(c.check(FileKind::Spell, None, "NOSUCHTAG").is_none());
        assert!(c.lookup("PCC", "GAMEMODE").is_some());
    }

    #[test]
    fn parse_tsv() {
        let c = Catalog::parse("# h\nSPELL\tSCHOOL\tactive\tcode\nGLOBAL\tOLD\tdeprecated\tdocs\n");
        assert_eq!(c.entries.len(), 2);
        assert_eq!(
            c.check(FileKind::Race, None, "OLD").unwrap().status,
            Status::Deprecated
        );
        assert!(c.check(FileKind::Race, None, "SCHOOL").is_none());
    }
}
